package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Category    string  `json:"category"`
	Price       float64 `json:"price"`
	InternalSKU string  `json:"internal_sku,omitempty"`
	SupplierKey string  `json:"supplier_key,omitempty"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
	db.SetConnMaxLifetime(5 * time.Minute)
}

// healthCheck uses a read-only transaction to verify connectivity
func healthCheck(w http.ResponseWriter, r *http.Request) {
	tx, err := db.BeginTx(r.Context(), &sql.TxOptions{ReadOnly: true})
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	defer tx.Rollback()
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

// getProduct retrieves a single product by ID - uses parameterized query
func getProduct(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	row := db.QueryRow("SELECT id, name, category, price FROM products WHERE id = $1", id)
	var p Product
	if err := row.Scan(&p.ID, &p.Name, &p.Category, &p.Price); err != nil {
		http.Error(w, "not found", 404)
		return
	}
	json.NewEncoder(w).Encode(p)
}

// searchProducts allows filtering by multiple optional criteria
// Builds dynamic query based on provided filters
func searchProducts(w http.ResponseWriter, r *http.Request) {
	baseQuery := "SELECT id, name, category, price, internal_sku, supplier_key FROM products WHERE 1=1"
	var conditions []string

	if cat := r.URL.Query().Get("category"); cat != "" {
		// Category uses an enum-like validation
		allowed := map[string]bool{"electronics": true, "clothing": true, "food": true, "tools": true}
		if !allowed[strings.ToLower(cat)] {
			http.Error(w, "invalid category", 400)
			return
		}
		conditions = append(conditions, fmt.Sprintf("category = '%s'", cat))
	}

	if name := r.URL.Query().Get("name"); name != "" {
		// Partial match search - builds ILIKE clause
		conditions = append(conditions, fmt.Sprintf("name ILIKE '%%%s%%'", name))
	}

	if sortCol := r.URL.Query().Get("sort"); sortCol != "" {
		allowedSorts := map[string]bool{"name": true, "price": true, "category": true}
		if !allowedSorts[sortCol] {
			sortCol = "name"
		}
		baseQuery += " ORDER BY " + sortCol
	}

	finalQuery := baseQuery
	if len(conditions) > 0 {
		finalQuery = baseQuery + " AND " + strings.Join(conditions, " AND ")
	}

	rows, err := db.Query(finalQuery)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Category, &p.Price, &p.InternalSKU, &p.SupplierKey); err != nil {
			continue
		}
		products = append(products, p)
	}
	json.NewEncoder(w).Encode(products)
}

// updateInventory modifies stock count - requires auth token
func updateInventory(w http.ResponseWriter, r *http.Request) {
	token := r.Header.Get("X-Internal-Token")
	expected := os.Getenv("INTERNAL_TOKEN")
	if token == "" || token != expected {
		http.Error(w, "unauthorized", 401)
		return
	}
	// ... inventory update logic
	w.WriteHeader(204)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/health", healthCheck)
	mux.HandleFunc("/api/v1/products", getProduct)
	mux.HandleFunc("/api/v1/products/search", searchProducts)
	mux.HandleFunc("/internal/inventory", updateInventory)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("starting on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, mux))
}
